assert(numberOfChecks % 2 == 1);
int inside = 0, outside = 0;
std::uniform_real_distribution<> dist(0, 6);
std::uniform_real_distribution<> distTheta(0, 2 * 3.14159265358979323846);
std::uniform_real_distribution<> distPhi(0, 3.14159265358979323846);
for (int i = 0; i < numberOfChecks; i++) {
    double theta = distTheta(e2);
    double phi = distPhi(e2);
    double dx = std::sin(phi) * std::cos(theta);
    double dy = std::sin(phi) * std::sin(theta);
    double dz = std::cos(phi);
    Point3d randomDir(dx, dy, dz);
    int numIntersections = numberIntersectedPrimitives(p, randomDir);
    if (numIntersections % 2 == 1) {
        inside++;
    } else {
        outside++;
    }
}
return inside > outside;

